	Add_Filter_Plugin('Filter_Plugin_PostArticle_Succeed','Lucky_page_archive_cache');     	 				 
	Add_Filter_Plugin('Filter_Plugin_ViewList_Template','Lucky_tags_set');      	 	 	 
	Add_Filter_Plugin('Filter_Plugin_Edit_Response','Lucky_InSet');       			 	
	Add_Filter_Plugin('Filter_Plugin_Edit_Response5','Lucky_Edit');          		
	Add_Filter_Plugin('Filter_Plugin_PostComment_Succeed','Lucky_MessageAvatar_Main');    	   	 		
	Add_Filter_Plugin('Filter_Plugin_PostArticle_Succeed','Lucky_MessageAvatar_Main');     	 		 	 
	Add_Filter_Plugin('Filter_Plugin_PostArticle_Succeed','Lucky_tab');     	 			 	
	Add_Filter_Plugin('Filter_Plugin_Index_Begin','Lucky_Usercenter');    			  	 	
	Add_Filter_Plugin('Filter_Plugin_Login_Header','Lucky_login');      	 	 	 
	Add_Filter_Plugin('Filter_Plugin_Category_Edit_Response','Lucky_Category_Edit_Response');     	  	   
	Add_Filter_Plugin('Filter_Plugin_Tag_Edit_Response','Lucky_Tag_Edit_Response');     	  		 	
	Add_Filter_Plugin('Filter_Plugin_Html_Js_Add','Lucky_AddJS');      		 	  
	Add_Filter_Plugin('Filter_Plugin_Html_Js_Add', 'Lucky_UBB_Js_Add');      		 	 	
	if ($zbp->Config('Lucky')->check_bdurl=='a'){    	  		 	 
		Add_Filter_Plugin('Filter_Plugin_ViewPost_Template','Lucky_baidu_recond_Page');      	     
	}     				 		
	if ($zbp->Config('Lucky')->canvas == 'a'){    	    	 	
		Add_Filter_Plugin('Filter_Plugin_Html_Js_Add','Lucky_Canvas_AddJS');     	     	
	}      		   	
