	Add_Filter_Plugin('Filter_Plugin_Template_GetTemplate','Lucky_GetArticleTemplate');    	  	 		 
	Add_Filter_Plugin('Filter_Plugin_Cmd_Ajax', 'Lucky_Ajax_QQinfo');    	 			 		
}       	 	 	
    	 		 	  
